from collections import Counter
from math import gcd

def transform(grid):
    counts = Counter(v for row in grid for v in row)
    common = {v for v, _ in counts.most_common(2)}
    fill = counts.most_common(1)[0][0]
    marker_colors = set(counts) - common

    marked = [
        (r, c) for r, row in enumerate(grid)
        for c, v in enumerate(row) if v in marker_colors
    ]
    rows_seen = sorted({r for r, _ in marked})
    cols_seen = sorted({c for _, c in marked})

    def lattice_positions(coords):
        step = 0
        for a, b in zip(coords, coords[1:]):
            step = gcd(step, b - a)
        if not step:
            return coords
        return list(range(coords[0], coords[-1] + 1, step))

    rs = lattice_positions(rows_seen)
    cs = lattice_positions(cols_seen)

    out = [[fill for _ in range(len(cs) - 1)] for _ in range(len(rs) - 1)]
    for i in range(len(rs) - 1):
        for j in range(len(cs) - 1):
            corners = [
                grid[rs[i]][cs[j]], grid[rs[i]][cs[j + 1]],
                grid[rs[i + 1]][cs[j]], grid[rs[i + 1]][cs[j + 1]]
            ]
            if corners[0] in marker_colors and all(v == corners[0] for v in corners):
                out[i][j] = corners[0]
    return out
